def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]

    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)

    colors = {grid[r][c] for r, c in cells}
    inner = next((color for color in colors
                  if any(grid[r][c] == color
                         for r in range(r0 + 1, r1)
                         for c in range(c0 + 1, c1))), None)
    if inner is None:
        return [row[:] for row in grid]

    # The frame thickness determines how far the inner color extends outward.
    top = next((r for r in range(r0, r1 + 1)
                if any(grid[r][c] == inner for c in range(c0, c1 + 1))), r0)
    bottom = next((r for r in range(r1, r0 - 1, -1)
                   if any(grid[r][c] == inner for c in range(c0, c1 + 1))), r1)
    left = next((c for c in range(c0, c1 + 1)
                 if any(grid[r][c] == inner for r in range(r0, r1 + 1))), c0)
    right = next((c for c in range(c1, c0 - 1, -1)
                  if any(grid[r][c] == inner for r in range(r0, r1 + 1))), c1)

    dr_top, dr_bottom = top - r0, r1 - bottom
    dc_left, dc_right = left - c0, c1 - right
    nr0, nr1 = max(0, r0 - dr_top), min(h - 1, r1 + dr_bottom)
    nc0, nc1 = max(0, c0 - dc_left), min(w - 1, c1 + dc_right)

    out = [row[:] for row in grid]
    for r in range(nr0, nr1 + 1):
        for c in range(nc0, nc1 + 1):
            if grid[r][c] == 0:
                out[r][c] = inner
    return out
